1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>GEMM Data Pipeline on Blackwell</title>
7	<link rel="stylesheet" href="../viz-base.css">
8	<script src="../viz-base.js"></script>
9	<style>
10	  body { padding: 14px 24px; max-width: 1300px; margin: 0 auto; }
11	  h1 { font-size: 28px; line-height: 1.1; margin-bottom: 8px; }
12	  .sub { font-size: 16px; line-height: 1.25; }
13	
14	  /* ── Pipeline (top) ──────────────────────────────────── */
15	  .pipeline {
16	    display: flex; align-items: center; justify-content: center;
17	    gap: 0; margin: 12px auto 18px; flex-wrap: nowrap;
18	  }
19	  .stage {
20	    display: flex; flex-direction: column; align-items: center;
21	    gap: 4px; flex-shrink: 0;
22	  }
23	  .stage-box {
24	    padding: 8px 10px; border-radius: 8px; text-align: center;
25	    font-weight: 700; font-size: 15px; line-height: 1.05; border: 2.5px solid;
26	    width: 86px; height: 54px; cursor: pointer;
27	    transition: all .3s ease;
28	    display: flex; flex-direction: column; align-items: center; justify-content: center;
29	  }
30	  .stage-box.dimmed { opacity: 0.2; }
31	  .stage-box span { font-size: 12.5px !important; line-height: 1.1; font-weight: 500; }
32	  .stage-sub { font-size: 12px; font-weight: 600; color: var(--dim); }
33	
34	  .s-gmem  { border-color: #6b7280; background: #f3f4f6; color: #374151; }
35	  .s-smem  { border-color: #8b5cf6; background: #ede9fe; color: #5b21b6; }
36	  .s-tmem  { border-color: #f59e0b; background: #fffbeb; color: #c2410c; }
37	  .s-reg   { border-color: #dc2626; background: #fee2e2; color: #991b1b; }
38	
39	  .arrow-h {
40	    display: flex; align-items: center; flex-direction: column;
41	    gap: 2px; flex-shrink: 0; padding: 0 2px;
42	  }
43	  .arrow-h svg { width: 34px; height: 16px; }
44	  .p-arrow-label {
45	    font-size: 12px; line-height: 1.1; font-weight: 700; white-space: nowrap;
46	    cursor: pointer; transition: all .2s;
47	    padding: 2px 5px; border-radius: 4px;
48	    background: rgba(0,0,0,.05);
49	  }
50	  .p-arrow-label:hover { background: rgba(0,0,0,.1); }
51	  .p-arrow-label.c-blue   { color: #3b82f6; }
52	  .p-arrow-label.c-green  { color: #059669; }
53	  .p-arrow-label.c-amber  { color: #f59e0b; }
54	  .p-arrow-label.c-red    { color: #dc2626; }
55	
56	  /* ── Architecture (bottom) ───────────────────────────── */
57	  .arch-wrap {
58	    max-width: 1000px; margin: 0 auto; position: relative;
59	  }
60	  .sm-box {
61	    border: 3px solid #334155; border-radius: 14px;
62	    background: #f8fafc; padding: 16px 20px 22px;
63	    position: relative; margin-bottom: 8px;
64	  }
65	  .sm-label {
66	    position: absolute; top: -12px; left: 24px;
67	    background: #334155; color: #fff; font-size: 13px; line-height: 1.1; font-weight: 700;
68	    padding: 2px 12px; border-radius: 4px; letter-spacing: .04em;
69	  }
70	
71	  .hw-unit {
72	    border: 2px solid; border-radius: 8px; padding: 8px 12px;
73	    text-align: center; cursor: pointer; transition: all .2s;
74	  }
75	  .hw-unit.dimmed { opacity: 0.15; }
76	  .hw-name { font-size: 16px; line-height: 1.05; font-weight: 700; margin-bottom: 1px; }
77	  .hw-sub  { font-size: 12.5px; line-height: 1.1; color: #64748b; }
78	
79	  .u-tc   { border-color: #059669; background: #dcfce7; }
80	  .u-tc .hw-name { color: #065f46; }
81	  .u-smem { border-color: #8b5cf6; background: #ede9fe; }
82	  .u-smem .hw-name { color: #5b21b6; }
83	  .u-tmem { border-color: #f59e0b; background: #fffbeb; }
84	  .u-tmem .hw-name { color: #c2410c; }
85	  .u-rf   { border-color: #dc2626; background: #fee2e2; }
86	  .u-rf .hw-name { color: #991b1b; }
87	  .u-tma  { border-color: #3b82f6; background: #dbeafe; }
88	  .u-tma .hw-name { color: #1e40af; }
89	  .u-cuda { border-color: #6b7280; background: #f3f4f6; }
90	  .u-cuda .hw-name { color: #374151; }
91	
92	  .row-compute {
93	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
94	    margin-bottom: 34px;
95	  }
96	  .row-mem {
97	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
98	    margin-bottom: 34px;
99	  }
100	  .row-tma {
101	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
102	  }
103	
104	  .hbm-box {
105	    border: 2.5px solid #6b7280; border-radius: 10px;
106	    background: #f3f4f6; color: #374151; padding: 10px 18px;
107	    text-align: center; transition: opacity .2s;
108	  }
109	  .hbm-box.dimmed { opacity: 0.15; }
110	  .hbm-name { font-size: 16px; line-height: 1.1; font-weight: 700; }
111	
112	  .svg-overlay {
113	    position: absolute; top: 0; left: 0;
114	    pointer-events: none; z-index: 10;
115	  }
116	  .svg-overlay .arrow-label {
117	    font-family: 'SF Mono','Fira Code',monospace;
118	    font-size: 12px; font-weight: 600;
119	  }
120	
121	  /* ── Detail panel ────────────────────────────────────── */
122	  .detail-panel {
123	    max-width: 1000px; margin: 10px auto 0;
124	    border: 1px solid var(--border); border-radius: 10px;
125	    background: var(--surface); padding: 10px 16px;
126	    min-height: 110px; transition: border-color .3s;
127	  }
128	  .detail-panel .dp-title { font-size: 14.5px; font-weight: 700; margin-bottom: 3px; }
129	  .detail-panel .dp-body { font-size: 14px; line-height: 1.32; color: #475569; }
130	  .detail-panel.empty .dp-body { color: #94a3b8; font-size: 16px; line-height: 1.3; }
131	
132	  .gpu-row {
133	    display: grid; grid-template-columns: 1fr auto; gap: 14px;
134	    align-items: stretch; margin-bottom: 8px;
135	  }
136	  .sm-ghost {
137	    border: 3px dashed #94a3b8; border-radius: 14px;
138	    background: #f1f5f9; min-width: 80px;
139	    display: flex; align-items: center; justify-content: center;
140	    color: #94a3b8; font-size: 14px; font-weight: 700;
141	    position: relative;
142	  }
143	  .sm-ghost-label {
144	    position: absolute; top: -12px; left: 14px;
145	    background: #94a3b8; color: #fff; font-size: 13px; line-height: 1.1; font-weight: 700;
146	    padding: 2px 10px; border-radius: 4px; letter-spacing: .04em;
147	  }
148	</style>
149	</head>
150	<body>
151	  <h1>GEMM Data Pipeline on Blackwell</h1>
152	  <p class="sub" style="margin-bottom:4px;">D = A × B — click an action to see the data path on the architecture</p>
153	
154	  <!-- ── Pipeline ──────────────────────────────────────── -->
155	  <div class="pipeline">
156	    <div class="stage">
157	      <div class="stage-box s-gmem" data-stage="gmem1">GMEM<br><span style="font-size:11px;font-weight:500;">A, B</span></div>
158	    </div>
159	    <div class="arrow-h">
160	      <svg viewBox="0 0 40 20"><path d="M2 10 H30" stroke="#3b82f6" stroke-width="2.5" fill="none"/><polygon points="28,5 38,10 28,15" fill="#3b82f6"/></svg>
161	      <div class="p-arrow-label c-blue" data-action="tma_load">TMA load</div>
162	    </div>
163	    <div class="stage">
164	      <div class="stage-box s-smem" data-stage="smem1">SMEM</div>
165	    </div>
166	    <div class="arrow-h">
167	      <svg viewBox="0 0 40 20"><path d="M2 10 H30" stroke="#059669" stroke-width="2.5" fill="none"/><polygon points="28,5 38,10 28,15" fill="#059669"/></svg>
168	      <div class="p-arrow-label c-green" data-action="mma">tcgen05.mma</div>
169	    </div>
170	    <div class="stage">
171	      <div class="stage-box s-tmem" data-stage="tmem">TMEM<br><span style="font-size:11px;font-weight:500;">accum</span></div>
172	    </div>
173	    <div class="arrow-h">
174	      <svg viewBox="0 0 40 20"><path d="M2 10 H30" stroke="#f59e0b" stroke-width="2.5" fill="none"/><polygon points="28,5 38,10 28,15" fill="#f59e0b"/></svg>
175	      <div class="p-arrow-label c-amber" data-action="ld">tcgen05.ld</div>
176	    </div>
177	    <div class="stage">
178	      <div class="stage-box s-reg" data-stage="reg">Reg<br><span style="font-size:11px;font-weight:500;">cast</span></div>
179	    </div>
180	    <div class="arrow-h">
181	      <svg viewBox="0 0 40 20"><path d="M2 10 H30" stroke="#dc2626" stroke-width="2.5" fill="none"/><polygon points="28,5 38,10 28,15" fill="#dc2626"/></svg>
182	      <div class="p-arrow-label c-red" data-action="store">store</div>
183	    </div>
184	    <div class="stage">
185	      <div class="stage-box s-smem" data-stage="smem2">SMEM</div>
186	    </div>
187	    <div class="arrow-h">
188	      <svg viewBox="0 0 40 20"><path d="M2 10 H30" stroke="#3b82f6" stroke-width="2.5" fill="none"/><polygon points="28,5 38,10 28,15" fill="#3b82f6"/></svg>
189	      <div class="p-arrow-label c-blue" data-action="tma_store">TMA store</div>
190	    </div>
191	    <div class="stage">
192	      <div class="stage-box s-gmem" data-stage="gmem2">GMEM<br><span style="font-size:11px;font-weight:500;">D</span></div>
193	    </div>
194	  </div>
195	
196	  <div style="max-width:1000px; margin:4px auto 10px; display:flex; align-items:center; gap:10px;">
197	    <div style="flex:1; height:1px; background:#e2e8f0;"></div>
198	    <span style="font-size:13px; font-weight:700; color:#94a3b8; letter-spacing:.05em; text-transform:uppercase;">Blackwell Architecture</span>
199	    <div style="flex:1; height:1px; background:#e2e8f0;"></div>
200	  </div>
201	
202	  <!-- ── Architecture diagram ──────────────────────────── -->
203	  <div class="arch-wrap" id="archWrap">
204	    <div class="gpu-row">
205	    <div class="sm-box" id="smBox" style="margin-bottom:0;">
206	      <div class="sm-label">Streaming Multiprocessor (SM)</div>
207	
208	      <div class="row-compute">
209	        <div class="hw-unit u-tc" data-unit="tc" id="boxTC">
210	          <div class="hw-name">Tensor Core (tcgen05)</div>
211	          <div class="hw-sub">5th-gen MMA</div>
212	        </div>
213	        <div></div>
214	        <div class="hw-unit u-cuda" data-unit="cuda" id="boxCUDA">
215	          <div class="hw-name">CUDA Core</div>
216	          <div class="hw-sub">FP/INT units</div>
217	        </div>
218	      </div>
219	
220	      <div class="row-mem">
221	        <div class="hw-unit u-smem" data-unit="smem" id="boxSMEM">
222	          <div class="hw-name">Shared Memory (SMEM)</div>
223	          <div class="hw-sub">228 KB per SM</div>
224	        </div>
225	        <div class="hw-unit u-tmem" data-unit="tmem" id="boxTMEM">
226	          <div class="hw-name">Tensor Memory (TMEM)</div>
227	          <div class="hw-sub">128 lanes</div>
228	        </div>
229	        <div class="hw-unit u-rf" data-unit="rf" id="boxRF">
230	          <div class="hw-name">Register File</div>
231	        </div>
232	      </div>
233	
234	      <div class="row-tma">
235	        <div class="hw-unit u-tma" data-unit="tma" id="boxTMA">
236	          <div class="hw-name">TMA Engine</div>
237	          <div class="hw-sub">Data Mover</div>
238	        </div>
239	        <div></div>
240	        <div></div>
241	      </div>
242	    </div>
243	    <div class="sm-ghost">
244	      <div class="sm-ghost-label">SM ...</div>
245	      &times; N
246	    </div>
247	    </div>
248	
249	    <div class="hbm-box" id="boxHBM">
250	      <div class="hbm-name">Global Memory (GMEM)</div>
251	    </div>
252	
253	    <!-- SVG overlay for data path arrows -->
254	    <svg class="svg-overlay" id="arrowSvg" style="display:none;">
255	      <defs>
256	        <marker id="ah-blue" markerWidth="6" markerHeight="4" refX="6" refY="2" orient="auto">
257	          <polygon points="0 0,6 2,0 4" fill="#3b82f6"/>
258	        </marker>
259	        <marker id="ah-green" markerWidth="6" markerHeight="4" refX="6" refY="2" orient="auto">
260	          <polygon points="0 0,6 2,0 4" fill="#059669"/>
261	        </marker>
262	        <marker id="ah-amber" markerWidth="6" markerHeight="4" refX="6" refY="2" orient="auto">
263	          <polygon points="0 0,6 2,0 4" fill="#f59e0b"/>
264	        </marker>
265	        <marker id="ah-red" markerWidth="6" markerHeight="4" refX="6" refY="2" orient="auto">
266	          <polygon points="0 0,6 2,0 4" fill="#dc2626"/>
267	        </marker>
268	      </defs>
269	      <!-- Load path — hidden by default -->
270	      <path id="arr1" class="arch-arrow" data-arrows="tma_load" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)" style="display:none;"/>
271	      <text id="lbl1" class="arrow-label" fill="#3b82f6" style="display:none;"></text>
272	      <path id="arr2" class="arch-arrow" data-arrows="tma_load" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)" style="display:none;"/>
273	      <text id="lbl2" class="arrow-label" fill="#3b82f6" style="display:none;"></text>
274	      <path id="arr3" class="arch-arrow" data-arrows="mma" stroke="#059669" stroke-width="2" fill="none" marker-end="url(#ah-green)" style="display:none;"/>
275	      <text id="lbl3" class="arrow-label" fill="#059669" style="display:none;"></text>
276	      <path id="arr4" class="arch-arrow" data-arrows="mma" stroke="#f59e0b" stroke-width="2" fill="none" marker-end="url(#ah-amber)" style="display:none;"/>
277	      <text id="lbl4" class="arrow-label" fill="#f59e0b" style="display:none;"></text>
278	      <path id="arr5" class="arch-arrow" data-arrows="ld" stroke="#dc2626" stroke-width="2" fill="none" marker-end="url(#ah-red)" style="display:none;"/>
279	      <text id="lbl5" class="arrow-label" fill="#dc2626" style="display:none;"></text>
280	      <!-- RF → SMEM (store) — hidden by default -->
281	      <path id="arr6" class="arch-arrow" data-arrows="store" stroke="#dc2626" stroke-width="2" fill="none" marker-end="url(#ah-red)" style="display:none;"/>
282	      <text id="lbl6" class="arrow-label" fill="#dc2626" style="display:none;"></text>
283	      <!-- Store path (dashed) — hidden by default -->
284	      <path id="arr7" class="arch-arrow" data-arrows="tma_store" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)" style="display:none;"/>
285	      <text id="lbl7" class="arrow-label" fill="#3b82f6" style="display:none;"></text>
286	      <path id="arr8" class="arch-arrow" data-arrows="tma_store" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)" style="display:none;"/>
287	      <text id="lbl8" class="arrow-label" fill="#3b82f6" style="display:none;"></text>
288	    </svg>
289	  </div>
290	
291	  <!-- Detail panel -->
292	  <div class="detail-panel empty" id="detailPanel">
293	    <div class="dp-title" id="dpTitle"></div>
294	    <div class="dp-body" id="dpBody">Click an action in the pipeline to highlight the data path.</div>
295	  </div>
296	
297	<script>
298	(function() {
299	  /* ── Action definitions ──────────────────────────────── */
300	  var actions = {
301	    tma_load:  { title: 'TMA Load — cp.async.bulk.tensor', color: '#3b82f6',
302	      body: 'TMA engine copies a tile from GMEM to SMEM. One thread issues the instruction; HW handles address calculation, swizzling, and async transfer.',
303	      pipeStages: ['gmem1', 'smem1'],
304	      archUnits: ['boxHBM', 'boxTMA', 'boxSMEM'],
305	      archArrows: 'tma_load' },
306	    mma:       { title: 'tcgen05.mma — Tensor Core MMA', color: '#059669',
307	      body: 'Tensor Core reads A/B tiles from SMEM and accumulates C += A × B into TMEM. Single warp issues; HW distributes across 128 TMEM lanes.',
308	      pipeStages: ['smem1', 'tmem'],
309	      archUnits: ['boxSMEM', 'boxTC', 'boxTMEM'],
310	      archArrows: 'mma' },
311	    ld:        { title: 'tcgen05.ld — Load from Tensor Memory', color: '#f59e0b',
312	      body: 'Reads accumulated fp32 results from TMEM into registers for writeback. Each thread gets its slice of the output tile.',
313	      pipeStages: ['tmem', 'reg'],
314	      archUnits: ['boxTMEM', 'boxRF'],
315	      archArrows: 'ld' },
316	    store:     { title: 'Store — Cast & Write to SMEM', color: '#dc2626',
317	      body: 'CUDA cores cast fp32 → fp16 in registers, then store results to SMEM writeback buffer for TMA to flush to GMEM.',
318	      pipeStages: ['reg', 'smem2'],
319	      archUnits: ['boxRF', 'boxCUDA', 'boxSMEM'],
320	      archArrows: 'store' },
321	    tma_store: { title: 'TMA Store — cp.async.bulk.tensor', color: '#3b82f6',
322	      body: 'TMA engine copies the fp16 result tile from SMEM writeback buffer back to GMEM. Async — overlaps with next iteration.',
323	      pipeStages: ['smem2', 'gmem2'],
324	      archUnits: ['boxSMEM', 'boxTMA', 'boxHBM'],
325	      archArrows: 'tma_store' }
326	  };
327	
328	  var panel = document.getElementById('detailPanel');
329	  var titleEl = document.getElementById('dpTitle');
330	  var bodyEl = document.getElementById('dpBody');
331	
332	  var pipeBoxes = document.querySelectorAll('.stage-box');
333	  var actionLabels = document.querySelectorAll('.p-arrow-label[data-action]');
334	  var archUnits = document.querySelectorAll('.hw-unit');
335	  var hbmBox = document.getElementById('boxHBM');
336	  var archArrows = document.querySelectorAll('.arch-arrow');
337	  var archLabels = document.querySelectorAll('.svg-overlay .arrow-label');
338	  var activeAction = null;
339	
340	  function clearAll() {
341	    activeAction = null;
342	    pipeBoxes.forEach(function(b) { b.classList.remove('selected', 'dimmed'); });
343	    actionLabels.forEach(function(l) { l.style.fontWeight = ''; });
344	    archUnits.forEach(function(u) { u.classList.remove('selected', 'dimmed'); });
345	    hbmBox.classList.remove('dimmed');
346	    archArrows.forEach(function(a) { a.style.opacity = ''; a.style.display = 'none'; });
347	    archLabels.forEach(function(l) { l.style.opacity = ''; l.style.display = 'none'; });
348	    panel.classList.add('empty');
349	    panel.style.borderColor = '';
350	    titleEl.textContent = '';
351	    bodyEl.innerHTML = 'Click an action in the pipeline to highlight the data path.';
352	  }
353	
354	  function showAction(key) {
355	    if (key === activeAction) { clearAll(); return; }
356	    clearAll();
357	    activeAction = key;
358	    var d = actions[key];
359	    if (!d) return;
360	
361	    /* Detail panel */
362	    panel.classList.remove('empty');
363	    panel.style.borderColor = d.color;
364	    titleEl.textContent = d.title;
365	    titleEl.style.color = d.color;
366	    bodyEl.textContent = d.body;
367	
368	    /* Pipeline: highlight involved stages, dim others */
369	    pipeBoxes.forEach(function(b) {
370	      if (d.pipeStages.indexOf(b.dataset.stage) >= 0) {
371	        b.classList.add('selected');
372	      } else {
373	        b.classList.add('dimmed');
374	      }
375	    });
376	
377	    /* Architecture: highlight involved units, dim others */
378	    var unitSet = d.archUnits;
379	    archUnits.forEach(function(u) {
380	      if (unitSet.indexOf(u.id) >= 0) {
381	        u.classList.add('selected');
382	      } else {
383	        u.classList.add('dimmed');
384	      }
385	    });
386	    if (unitSet.indexOf('boxHBM') < 0) {
387	      hbmBox.classList.add('dimmed');
388	    }
389	
390	    /* Architecture: show only matching arrows */
391	    if (d.archArrows) {
392	      archArrows.forEach(function(a) {
393	        if (a.dataset.arrows === d.archArrows) {
394	          a.style.display = '';
395	          var lblId = 'lbl' + a.id.replace('arr', '');
396	          var lbl = document.getElementById(lblId);
397	          if (lbl) lbl.style.display = '';
398	        }
399	      });
400	    }
401	  }
402	
403	  actionLabels.forEach(function(el) {
404	    el.addEventListener('click', function() {
405	      showAction(el.dataset.action);
406	    });
407	  });
408	
409	  pipeBoxes.forEach(function(el) {
410	    el.addEventListener('click', function() {
411	      clearAll();
412	    });
413	  });
414	
415	  archUnits.forEach(function(el) {
416	    el.addEventListener('click', function() {
417	      clearAll();
418	    });
419	  });
420	
421	  /* ── Arrow positioning ───────────────────────────────── */
422	  function positionArrows() {
423	    var svg = document.getElementById('arrowSvg');
424	    var wrap = document.getElementById('archWrap');
425	    var wr = wrap.getBoundingClientRect();
426	
427	    svg.style.display = 'block';
428	    svg.setAttribute('width', wr.width);
429	    svg.setAttribute('height', wr.height);
430	
431	    function rel(el) {
432	      var r = el.getBoundingClientRect();
433	      return {
434	        top: r.top - wr.top, bottom: r.bottom - wr.top,
435	        left: r.left - wr.left, right: r.right - wr.left,
